                key={`usage-pace-left-${window.kind}`}
                width={markerCell}
                flexShrink={0}
                justifyContent={isPaceRevealed && copyOnLeft ? "flex-end" : undefined}
                height={1}
                flexDirection="row"
                overflow="hidden"
