  return (
    <Box
      key="usage-band"
      position="relative"
      flexDirection="row"
      alignItems={isDesktop ? "center" : "flex-end"}
      gap={isDesktop ? 0 : 1}
    >
      {isDesktop && <Box width={PRESENTATION.brandInset / 8} flexShrink={0} />}
      {mark}
      {isDesktop && <Box width={PRESENTATION.brandGap / 8} flexShrink={0} />}
